SAVED_WALLS_FALLBACK_FILE = Path(__file__).with_name(".wall_saved_assemblies.json")

try:
    BROWSER_STORAGE = LocalStorage() if LocalStorage is not None else None
except Exception:
    BROWSER_STORAGE = None


def _decode_custom_library(value: Any) -> list[dict[str, Any]] | None:
    if value in (None, "", []):
        return None
    try:
        if isinstance(value, str):
            value = json.loads(value)
        if isinstance(value, dict):
            value = value.get("value", value.get("data", value.get("custom_library")))
            if isinstance(value, str):
                value = json.loads(value)
        if isinstance(value, list):
            return normalize_custom_library(value)
    except (TypeError, ValueError, json.JSONDecodeError):
        return None
    return None


def _load_fallback_custom_library() -> list[dict[str, Any]]:
    try:
        if CUSTOM_LIBRARY_FALLBACK_FILE.exists():
            data = json.loads(CUSTOM_LIBRARY_FALLBACK_FILE.read_text(encoding="utf-8"))
            return normalize_custom_library(data if isinstance(data, list) else [])
    except (OSError, ValueError, json.JSONDecodeError):
        pass
    return []


def persist_custom_library() -> None:
    st.session_state.custom_library = normalize_custom_library(st.session_state.custom_library)
    payload = json.dumps(st.session_state.custom_library, ensure_ascii=False)
    if BROWSER_STORAGE is not None:
        st.session_state._custom_storage_write_number = st.session_state.get("_custom_storage_write_number", 0) + 1
        try:
            BROWSER_STORAGE.setItem(
                CUSTOM_LIBRARY_STORAGE_KEY,
                payload,
                key=f"custom_library_write_{st.session_state._custom_storage_write_number}",
            )
        except TypeError:
            BROWSER_STORAGE.setItem(CUSTOM_LIBRARY_STORAGE_KEY, payload)
        # The browser component needs a moment to write before a forced rerun.
        time.sleep(0.8)
    else:
        try:
            CUSTOM_LIBRARY_FALLBACK_FILE.write_text(payload, encoding="utf-8")
        except OSError:
            pass


def hydrate_custom_library() -> None:
    if st.session_state.get("_custom_library_hydrated"):
        return

    if BROWSER_STORAGE is not None:
        try:
            returned = BROWSER_STORAGE.getItem(
                CUSTOM_LIBRARY_STORAGE_KEY,
                key="custom_library_storage_read",
            )
        except TypeError:
            returned = BROWSER_STORAGE.getItem(CUSTOM_LIBRARY_STORAGE_KEY)
        stored = st.session_state.get("custom_library_storage_read", returned)
        decoded = _decode_custom_library(stored)
        if decoded is not None and not st.session_state.get("_custom_library_dirty"):
            st.session_state.custom_library = decoded
            st.session_state._custom_library_hydrated = True
    else:
        st.session_state.custom_library = _load_fallback_custom_library()
        st.session_state._custom_library_hydrated = True


def mark_custom_library_changed() -> None:
    st.session_state._custom_library_dirty = True
    st.session_state._custom_library_hydrated = True
    persist_custom_library()


def normalize_saved_walls(items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Normalize saved full-wall templates loaded from browser storage."""
    normalized: list[dict[str, Any]] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        raw_assembly = item.get("assembly", item)
        if not isinstance(raw_assembly, dict):
            continue
        assembly = normalize_assembly(copy.deepcopy(raw_assembly))
        name = str(item.get("name") or assembly.get("name") or "Saved wall").strip() or "Saved wall"
        normalized.append({
            "id": str(item.get("template_id") or item.get("id") or uuid.uuid4().hex),
            "name": name,
            "assembly": assembly,
        })
    return normalized


def _decode_saved_walls(value: Any) -> list[dict[str, Any]] | None:
    if value in (None, "", []):
        return None
    try:
        if isinstance(value, str):
            value = json.loads(value)
        if isinstance(value, dict):
            value = value.get("value", value.get("data", value.get("saved_walls")))
            if isinstance(value, str):
                value = json.loads(value)
        if isinstance(value, list):
            return normalize_saved_walls(value)
    except (TypeError, ValueError, json.JSONDecodeError):
        return None
    return None


def _load_fallback_saved_walls() -> list[dict[str, Any]]:
    try:
        if SAVED_WALLS_FALLBACK_FILE.exists():
            data = json.loads(SAVED_WALLS_FALLBACK_FILE.read_text(encoding="utf-8"))
            return normalize_saved_walls(data if isinstance(data, list) else [])
    except (OSError, ValueError, json.JSONDecodeError):
        pass
    return []


def persist_saved_walls() -> None:
    st.session_state.saved_walls = normalize_saved_walls(st.session_state.saved_walls)
    payload = json.dumps(st.session_state.saved_walls, ensure_ascii=False)
    if BROWSER_STORAGE is not None:
        st.session_state._saved_walls_storage_write_number = st.session_state.get(
            "_saved_walls_storage_write_number", 0
        ) + 1
        try:
            BROWSER_STORAGE.setItem(
                SAVED_WALLS_STORAGE_KEY,
                payload,
                key=f"saved_walls_write_{st.session_state._saved_walls_storage_write_number}",
            )
        except TypeError:
            BROWSER_STORAGE.setItem(SAVED_WALLS_STORAGE_KEY, payload)
        time.sleep(0.8)
    else:
        try:
            SAVED_WALLS_FALLBACK_FILE.write_text(payload, encoding="utf-8")
        except OSError:
            pass


def hydrate_saved_walls() -> None:
    if st.session_state.get("_saved_walls_hydrated"):
        return

    if BROWSER_STORAGE is not None:
        try:
            returned = BROWSER_STORAGE.getItem(
                SAVED_WALLS_STORAGE_KEY,
                key="saved_walls_storage_read",
            )
        except TypeError:
            returned = BROWSER_STORAGE.getItem(SAVED_WALLS_STORAGE_KEY)
        stored = st.session_state.get("saved_walls_storage_read", returned)
        decoded = _decode_saved_walls(stored)
        if decoded is not None and not st.session_state.get("_saved_walls_dirty"):
            st.session_state.saved_walls = decoded
            st.session_state._saved_walls_hydrated = True
    else:
        st.session_state.saved_walls = _load_fallback_saved_walls()
        st.session_state._saved_walls_hydrated = True


def mark_saved_walls_changed() -> None:
    st.session_state._saved_walls_dirty = True
    st.session_state._saved_walls_hydrated = True
    persist_saved_walls()


def snapshot_assembly_for_saved_wall(assembly: dict[str, Any]) -> dict[str, Any]:
    """Create a self-contained full-wall snapshot for later reuse."""
    snapshot = normalize_assembly(copy.deepcopy(assembly))
    custom_library_names = {item["name"] for item in st.session_state.custom_library}

    # Embed custom-library EPD values so the saved wall remains complete even if
    # that custom material is later renamed or removed from the library.
    for material in snapshot.get("materials", []):
        if material.get("preset") not in custom_library_names:
            continue
        epd = material_lookup(material.get("preset", ""))
        if epd is None:
            continue
        material["preset"] = "Custom EPD"
        material["custom_name"] = epd["name"]
        material["custom_emitted"] = float(epd.get("emitted", 0.0))
        material["custom_stored"] = float(epd.get("stored", 0.0))
        material["custom_unit"] = epd.get("unit", "kgCO₂e/m²")

    return snapshot


def save_current_wall(assembly: dict[str, Any]) -> str:
    """Save the current full wall; an existing saved wall with the same name is updated."""
    name = str(assembly.get("name") or "Saved wall").strip() or "Saved wall"
    snapshot = snapshot_assembly_for_saved_wall(assembly)
    existing = next(
        (item for item in st.session_state.saved_walls if item["name"].casefold() == name.casefold()),
        None,
    )
    if existing is None:
        st.session_state.saved_walls.append({
            "id": uuid.uuid4().hex,
            "name": name,
            "assembly": snapshot,
        })
        action = "saved"
    else:
        existing["name"] = name
        existing["assembly"] = snapshot
        action = "updated"
    mark_saved_walls_changed()
    return action


def unique_assembly_name(base_name: str) -> str:
    existing = {str(item.get("name", "")).casefold() for item in st.session_state.assemblies}
    base = base_name.strip() or "Saved wall"
    if base.casefold() not in existing:
        return base
    number = 2
    while f"{base} ({number})".casefold() in existing:
        number += 1
    return f"{base} ({number})"


def assembly_from_saved_wall(saved_wall: dict[str, Any]) -> dict[str, Any]:
    assembly = copy.deepcopy(saved_wall["assembly"])
    assembly["id"] = uuid.uuid4().hex
    assembly["name"] = unique_assembly_name(saved_wall["name"])
    for material in assembly.get("materials", []):
        material["id"] = uuid.uuid4().hex
    return normalize_assembly(assembly)


def update_custom_material_references(old_name: str, new_name: str | None) -> None:
    replacement = new_name or "None"
    for assembly in st.session_state.assemblies:
        for material in assembly.get("materials", []):
            if material.get("preset") == old_name:
                material["preset"] = replacement


# =============================================================================
# PASSWORD-PROTECTED STUDIO G SHARED LIBRARY
# =============================================================================

STUDIO_G_MATERIALS_TABLE = "wall_e_materials"
STUDIO_G_WALLS_TABLE = "wall_e_assemblies"
STUDIO_G_REQUEST_TIMEOUT_SECONDS = 20


class StudioGLibraryError(RuntimeError):
    """Raised when the protected Studio G database cannot complete a request."""


def _read_streamlit_secrets() -> dict[str, Any]:
    """Read optional secrets without breaking the public calculator when none exist."""
    try:
        return dict(st.secrets)
    except Exception:
        return {}


def studio_g_library_config() -> dict[str, str]:
    """Return protected-library settings from Streamlit secrets.

    Preferred format:

        [studio_g_library]
        password = "..."
        supabase_url = "https://PROJECT.supabase.co"
        supabase_secret_key = "sb_secret_..."

    Legacy root-level names are also accepted to make upgrades easier.
    """
    secrets = _read_streamlit_secrets()
    section_raw = secrets.get("studio_g_library", {})
    try:
        section = dict(section_raw)
    except Exception:
        section = {}

    def pick(*names: str) -> str:
        for name in names:
            value = section.get(name)
            if value in (None, ""):
                value = secrets.get(name)
            if value not in (None, ""):
                return str(value).strip()
        return ""

    return {
        "password": pick("password", "STUDIO_G_LIBRARY_PASSWORD"),
        "supabase_url": pick("supabase_url", "SUPABASE_URL").rstrip("/"),
        "supabase_secret_key": pick(
            "supabase_secret_key",
            "SUPABASE_SECRET_KEY",
            "SUPABASE_SERVICE_ROLE_KEY",
        ),
    }


def studio_g_missing_settings() -> list[str]:
    config = studio_g_library_config()
    labels = {
        "password": "password",
        "supabase_url": "Supabase URL",
        "supabase_secret_key": "Supabase secret key",
    }
    return [labels[key] for key, value in config.items() if not value]


def studio_g_is_unlocked() -> bool:
    return bool(st.session_state.get("studio_g_library_unlocked", False))


def attempt_studio_g_unlock(password: str) -> tuple[bool, str]:
    """Validate the shared password with a small session-based brute-force delay."""
    missing = studio_g_missing_settings()
    if missing:
        return False, "Studio G Library is not configured yet."

    now = time.time()
    lock_until = float(st.session_state.get("studio_g_lock_until", 0.0))
    if lock_until > now:
        wait_seconds = max(1, math.ceil(lock_until - now))
        return False, f"Too many incorrect attempts. Try again in {wait_seconds} seconds."

    expected = studio_g_library_config()["password"]
    supplied = password or ""
    if hmac.compare_digest(supplied.encode("utf-8"), expected.encode("utf-8")):
        st.session_state.studio_g_library_unlocked = True
        st.session_state.studio_g_failed_attempts = 0
        st.session_state.studio_g_lock_until = 0.0
        st.session_state.studio_g_library_loaded = False
        return True, "Studio G Library unlocked."

    attempts = int(st.session_state.get("studio_g_failed_attempts", 0)) + 1
    st.session_state.studio_g_failed_attempts = attempts
    if attempts >= 5:
        st.session_state.studio_g_lock_until = now + 60
        st.session_state.studio_g_failed_attempts = 0
        return False, "Too many incorrect attempts. The password form is locked for 60 seconds."

    # Slow repeated guesses without affecting ordinary calculator use.
    time.sleep(min(0.5 * attempts, 2.0))
    return False, "Incorrect Studio G Library password."


def lock_studio_g_library() -> None:
    st.session_state.studio_g_library_unlocked = False
    st.session_state.studio_g_library_loaded = False
    st.session_state.studio_g_shared_materials = []
    st.session_state.studio_g_shared_walls = []
    st.session_state.studio_g_editing_material_id = None


def _supabase_headers(secret_key: str, prefer: str | None = None) -> dict[str, str]:
    headers = {
        "apikey": secret_key,
        "Accept": "application/json",
        "Content-Type": "application/json",
    }
    # New sb_secret_ keys are opaque API keys and must not be sent as Bearer JWTs.
    # Legacy service_role keys are JWTs and use both headers for RLS bypass.
    if not secret_key.startswith("sb_secret_"):
        headers["Authorization"] = f"Bearer {secret_key}"
    if prefer:
        headers["Prefer"] = prefer
    return headers


def studio_g_database_request(
    method: str,
    table: str,
    *,
    params: dict[str, str] | None = None,
    payload: dict[str, Any] | None = None,
    prefer: str | None = None,
) -> Any:
    """Call Supabase's server-side Data REST API using protected Streamlit secrets."""
    if not studio_g_is_unlocked():
        raise StudioGLibraryError("Unlock Studio G Library before accessing the shared database.")

    config = studio_g_library_config()
    if not config["supabase_url"] or not config["supabase_secret_key"]:
        raise StudioGLibraryError("The Studio G database connection is not configured.")

    endpoint = f'{config["supabase_url"]}/rest/v1/{table}'
    try:
        response = requests.request(
            method=method,
            url=endpoint,
            headers=_supabase_headers(config["supabase_secret_key"], prefer),
            params=params,
            json=payload,
            timeout=STUDIO_G_REQUEST_TIMEOUT_SECONDS,
        )
    except requests.RequestException as exc:
        raise StudioGLibraryError(f"Could not reach the Studio G database: {exc}") from exc

    if response.status_code >= 400:
        detail = ""
        try:
            body = response.json()
            detail = str(body.get("message") or body.get("details") or body.get("hint") or "")
        except (ValueError, TypeError, AttributeError):
            detail = response.text.strip()
        detail = detail[:300]
        suffix = f" {detail}" if detail else ""
        raise StudioGLibraryError(
            f"Studio G database request failed ({response.status_code}).{suffix}"
        )

    if response.status_code == 204 or not response.content:
        return None
    try:
        return response.json()
    except ValueError:
        return None


def _shared_material_from_row(row: dict[str, Any]) -> dict[str, Any]:
    unit = str(row.get("unit") or "kgCO₂e/m²")
    return {
        "id": str(row.get("id") or ""),
        "category": normalized_category(str(row.get("category") or "Interior Finishes")),
        "name": str(row.get("name") or "Shared material").strip() or "Shared material",
        "emitted": float(row.get("emitted") or 0.0),
        "stored": float(row.get("stored") or 0.0),
        "unit": unit if unit in DECLARED_UNITS else "kgCO₂e/m²",
        "method": method_from_declared_unit(unit),
        "source": str(row.get("source") or "Studio G shared library"),
        "source_declared_unit": str(row.get("source_declared_unit") or ""),
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
    }


def _shared_wall_from_row(row: dict[str, Any]) -> dict[str, Any]:
    raw_assembly = row.get("assembly")
    if not isinstance(raw_assembly, dict):
        raw_assembly = new_assembly(1)
    assembly = normalize_assembly(copy.deepcopy(raw_assembly))
    name = str(row.get("name") or assembly.get("name") or "Shared wall").strip() or "Shared wall"
    assembly["name"] = name
    return {
        "id": str(row.get("id") or ""),
        "name": name,
        "assembly": assembly,
        "created_at": row.get("created_at"),
        "updated_at": row.get("updated_at"),
    }


def refresh_studio_g_library() -> None:
    materials = studio_g_database_request(
        "GET",
        STUDIO_G_MATERIALS_TABLE,
        params={
            "select": "id,name,category,emitted,stored,unit,source,source_declared_unit,created_at,updated_at",
            "order": "name.asc",
        },
    ) or []
    walls = studio_g_database_request(
        "GET",
        STUDIO_G_WALLS_TABLE,
        params={
            "select": "id,name,assembly,created_at,updated_at",
            "order": "name.asc",
        },
    ) or []
    st.session_state.studio_g_shared_materials = [
        _shared_material_from_row(row) for row in materials if isinstance(row, dict)
    ]
    st.session_state.studio_g_shared_walls = [
        _shared_wall_from_row(row) for row in walls if isinstance(row, dict)
    ]
    st.session_state.studio_g_library_loaded = True


def _utc_timestamp() -> str:
    return datetime.utcnow().isoformat(timespec="seconds") + "Z"


def save_material_to_studio_g_database(
    material: dict[str, Any],
    *,
    existing_id: str | None = None,
) -> str:
    clean_name = str(material.get("name") or "").strip()
    if not clean_name:
        raise StudioGLibraryError("Enter a material name.")
    if any(
        str(item.get("name", "")).casefold() == clean_name.casefold()
        for item in PRESET_MATERIALS
    ):
        raise StudioGLibraryError("A preset material already uses this name.")
    unit = str(material.get("unit") or "kgCO₂e/m²")
    if unit not in DECLARED_UNITS:
        raise StudioGLibraryError("Choose a supported declared unit.")

    payload = {
        "name": clean_name,
        "category": normalized_category(str(material.get("category") or "Interior Finishes")),
        "emitted": float(material.get("emitted") or 0.0),
        "stored": float(material.get("stored") or 0.0),
        "unit": unit,
        "source": str(material.get("source") or "Studio G shared library").strip()
        or "Studio G shared library",
        "source_declared_unit": str(material.get("source_declared_unit") or ""),
        "updated_at": _utc_timestamp(),
    }

    shared_rows = st.session_state.get("studio_g_shared_materials", [])
    existing = None
    if existing_id:
        existing = next((item for item in shared_rows if item.get("id") == existing_id), None)
    if existing is None:
        existing = next(
            (item for item in shared_rows if str(item.get("name", "")).casefold() == clean_name.casefold()),
            None,
        )

    if existing:
        studio_g_database_request(
            "PATCH",
            STUDIO_G_MATERIALS_TABLE,
            params={"id": f'eq.{existing["id"]}'},
            payload=payload,
            prefer="return=representation",
        )
        action = "updated"
    else:
        studio_g_database_request(
            "POST",
            STUDIO_G_MATERIALS_TABLE,
            payload=payload,
            prefer="return=representation",
        )
        action = "saved"
    refresh_studio_g_library()
    return action


def delete_material_from_studio_g_database(material_id: str) -> None:
    studio_g_database_request(
        "DELETE",
        STUDIO_G_MATERIALS_TABLE,
        params={"id": f"eq.{material_id}"},
        prefer="return=minimal",
    )
    refresh_studio_g_library()


def save_wall_to_studio_g_database(assembly: dict[str, Any]) -> str:
    name = str(assembly.get("name") or "Shared wall").strip() or "Shared wall"
    payload = {
        "name": name,
        "assembly": snapshot_assembly_for_saved_wall(assembly),
        "updated_at": _utc_timestamp(),
    }
    existing = next(
        (
            item
            for item in st.session_state.get("studio_g_shared_walls", [])
            if str(item.get("name", "")).casefold() == name.casefold()
        ),
        None,
    )
    if existing:
        studio_g_database_request(
            "PATCH",
            STUDIO_G_WALLS_TABLE,
            params={"id": f'eq.{existing["id"]}'},
            payload=payload,
            prefer="return=representation",
        )
        action = "updated"
    else:
        studio_g_database_request(
            "POST",
            STUDIO_G_WALLS_TABLE,
            payload=payload,
            prefer="return=representation",
        )
        action = "saved"
    refresh_studio_g_library()
    return action


def delete_wall_from_studio_g_database(wall_id: str) -> None:
    studio_g_database_request(
        "DELETE",
        STUDIO_G_WALLS_TABLE,
        params={"id": f"eq.{wall_id}"},
        prefer="return=minimal",
    )
    refresh_studio_g_library()


def copy_shared_material_to_browser(material: dict[str, Any]) -> str:
    name = str(material.get("name") or "").strip()
    preset_match = next(
        (item for item in PRESET_MATERIALS if str(item.get("name", "")).casefold() == name.casefold()),
        None,
    )
    if preset_match:
        raise StudioGLibraryError("A preset material already uses this name.")

    local = next(
        (
            item
            for item in st.session_state.custom_library
            if str(item.get("name", "")).casefold() == name.casefold()
        ),
        None,
    )
    values = {
        "category": normalized_category(material.get("category")),
        "name": name,
        "emitted": float(material.get("emitted") or 0.0),
        "stored": float(material.get("stored") or 0.0),
        "unit": material.get("unit", "kgCO₂e/m²"),
        "method": method_from_declared_unit(material.get("unit", "kgCO₂e/m²")),
        "source": material.get("source") or "Studio G shared library",
        "source_declared_unit": material.get("source_declared_unit", ""),
    }
    if local:
        old_name = local["name"]
        local.update(values)
        update_custom_material_references(old_name, name)
        action = "updated in this browser"
    else:
        st.session_state.custom_library.append({"id": uuid.uuid4().hex, **values})
        action = "copied to this browser"
    mark_custom_library_changed()
    return action


def copy_shared_wall_to_browser_saved_walls(shared_wall: dict[str, Any]) -> str:
    saved = {
        "id": uuid.uuid4().hex,
        "name": shared_wall["name"],
        "assembly": normalize_assembly(copy.deepcopy(shared_wall["assembly"])),
    }
    existing = next(
        (
            item
            for item in st.session_state.saved_walls
            if str(item.get("name", "")).casefold() == saved["name"].casefold()
        ),
        None,
    )
    if existing:
        existing["assembly"] = saved["assembly"]
        existing["name"] = saved["name"]
        action = "updated in this browser"
    else:
        st.session_state.saved_walls.append(saved)
        action = "copied to this browser"
    mark_saved_walls_changed()
    return action


def initialize_state() -> None:
    if "assemblies" not in st.session_state:
        first = new_assembly(1)
        st.session_state.assemblies = [first]
        st.session_state.active_assembly_id = first["id"]
    else:
        st.session_state.assemblies = [normalize_assembly(item) for item in st.session_state.assemblies]

    if "custom_library" not in st.session_state:
        st.session_state.custom_library = []
    else:
        st.session_state.custom_library = normalize_custom_library(st.session_state.custom_library)

    if "saved_walls" not in st.session_state:
        st.session_state.saved_walls = []
    else:
        st.session_state.saved_walls = normalize_saved_walls(st.session_state.saved_walls)

    if "page" not in st.session_state:
        st.session_state.page = "Build Assemblies"
    if "show_add_custom" not in st.session_state:
        st.session_state.show_add_custom = False
    if "editing_custom_id" not in st.session_state:
        st.session_state.editing_custom_id = None
    if "studio_g_library_unlocked" not in st.session_state:
        st.session_state.studio_g_library_unlocked = False
    if "studio_g_library_loaded" not in st.session_state:
        st.session_state.studio_g_library_loaded = False
    if "studio_g_shared_materials" not in st.session_state:
        st.session_state.studio_g_shared_materials = []
    if "studio_g_shared_walls" not in st.session_state:
        st.session_state.studio_g_shared_walls = []
    if "studio_g_editing_material_id" not in st.session_state:
        st.session_state.studio_g_editing_material_id = None


initialize_state()
hydrate_custom_library()
hydrate_saved_walls()


def all_library_materials() -> list[dict[str, Any]]:
    return PRESET_MATERIALS + st.session_state.custom_library


def material_lookup(name: str) -> dict[str, Any] | None:
    for item in all_library_materials():
        if item["name"] == name:
            return item
    return None


def material_name_exists(name: str, exclude_custom_id: str | None = None) -> bool:
    target = name.strip().casefold()
    if not target:
        return False
    for item in PRESET_MATERIALS:
        if str(item.get("name", "")).strip().casefold() == target:
            return True
    for item in st.session_state.custom_library:
        if item.get("id") == exclude_custom_id:
            continue
        if str(item.get("name", "")).strip().casefold() == target:
            return True
    return False


def category_list() -> list[str]:
    return STARTING_CATEGORIES.copy()


def presets_for_category(category: str) -> list[str]:
    names = [item["name"] for item in all_library_materials() if item["category"] == category]
    return ["None"] + names + ["Custom EPD"]


def material_is_selected(material: dict[str, Any]) -> bool:
    return material.get("preset") not in EMPTY_PRESET_NAMES


def get_active_assembly() -> dict[str, Any]:
    active = st.session_state.active_assembly_id
    for assembly in st.session_state.assemblies:
        if assembly["id"] == active:
            return assembly
    st.session_state.active_assembly_id = st.session_state.assemblies[0]["id"]
    return st.session_state.assemblies[0]


BUILD_ASSEMBLY_PICKER_KEY = "build_assembly_picker"
PENDING_BUILD_ASSEMBLY_PICKER_KEY = "_pending_build_assembly_picker"
SAVED_WALL_PICKER_KEY = "saved_wall_picker"


def request_active_assembly(assembly_id: str) -> None:
    """Select a wall on the next rerun without overwriting a user's dropdown choice."""
    st.session_state.active_assembly_id = assembly_id
    st.session_state[PENDING_BUILD_ASSEMBLY_PICKER_KEY] = assembly_id


def move_assembly(assembly_id: str, offset: int) -> None:
    """Move one wall option one place up or down in the dropdown order."""
    assemblies = list(st.session_state.assemblies)
    current_index = next(
        (index for index, item in enumerate(assemblies) if item["id"] == assembly_id),
        None,
    )
    if current_index is None:
        return

    new_index = current_index + offset
    if new_index < 0 or new_index >= len(assemblies):
        return

    assemblies[current_index], assemblies[new_index] = (
        assemblies[new_index],
        assemblies[current_index],
    )
    st.session_state.assemblies = assemblies
    st.session_state.active_assembly_id = assembly_id


def select_index(options: list[Any], value: Any, fallback: int = 0) -> int:
    try:
        return options.index(value)
    except ValueError:
        return fallback


def input_value(material: dict[str, Any], key: str, default: Any) -> Any:
    return material.setdefault("inputs", {}).get(key, default)


def set_input(material: dict[str, Any], key: str, value: Any) -> Any:
    material.setdefault("inputs", {})[key] = value
    return value

# =============================================================================
# CALCULATION ENGINE — DIRECT TRANSLATION OF THE EXCEL FORMULAS
# =============================================================================


def member_count(span_ft: float, spacing_in: float, include_edges: str) -> int:
    if spacing_in <= 0:
        raise ValueError("Spacing must be greater than zero.")
    return max(1, math.ceil(span_ft * 12.0 / spacing_in) + (1 if include_edges == "Yes" else 0))


def effective_epd(material: dict[str, Any]) -> dict[str, Any] | None:
    if material.get("preset") in CUSTOM_PRESET_NAMES:
        return {
            "category": material.get("category", "Interior Finishes"),
            "name": material.get("custom_name", "").strip() or "Custom material",
            "emitted": float(material.get("custom_emitted", 0.0)),
            "stored": float(material.get("custom_stored", 0.0)),
            "unit": material.get("custom_unit", "kgCO₂e/m²"),
            "method": method_from_declared_unit(material.get("custom_unit", "kgCO₂e/m²")),
            "source": "Custom EPD entered by user",
            "source_declared_unit": "",
        }
    return material_lookup(material.get("preset", ""))


def calculate_material(assembly: dict[str, Any], material: dict[str, Any]) -> dict[str, Any]:
    width_ft = float(assembly.get("width_ft", 0.0))
    height_ft = float(assembly.get("height_ft", 0.0))
    area_ft2 = width_ft * height_ft
    area_m2 = area_ft2 * FT2_TO_M2

    base = {
        "valid": False,
        "status": "Not selected" if not material_is_selected(material) else "Check inputs",
        "error": "",
        "quantity": 0.0,
        "quantity_unit": "",
        "emitted": 0.0,
        "stored": 0.0,
        "net": 0.0,
        "emitted_intensity": 0.0,
        "net_intensity": 0.0,
        "name": material.get("custom_name") or material.get("preset") or "Unselected material",
        "category": material.get("category", "Interior Finishes"),
        "method": "",
        "unit": "",
        "formula_note": "",
    }

    if not material_is_selected(material):
        base["name"] = "None"
        return base
    if width_ft <= 0 or height_ft <= 0:
        base["error"] = "Enter wall width and height."
        return base

    epd = effective_epd(material)
    if epd is None:
        base["status"] = "Select material"
        base["error"] = "Select a preset material or choose Custom EPD."
        return base
    if material.get("preset") in CUSTOM_PRESET_NAMES and not material.get("custom_name", "").strip():
        base["status"] = "Complete custom EPD"
        base["error"] = "Enter a custom material name."
        return base

    method = epd["method"]
    inputs = material.get("inputs", {})
    quantity = 0.0
    quantity_unit = ""
    note = ""

    try:
        if method == "Area":
            quantity = area_m2
            quantity_unit = "m²"
            note = "wall area (ft²) × 0.09290304"

        elif method == "Volume Layer":
            thickness_in = float(inputs.get("thickness_in", 0.0))
            if thickness_in <= 0:
                raise ValueError("Enter product thickness in inches.")
            quantity = area_m2 * thickness_in * IN_TO_M
            quantity_unit = "m³"
            note = "wall area (m²) × thickness (in) × 0.0254"

        elif method == "Mass by Grammage":
            mass_input_method = inputs.get("mass_input_method", "Use grammage (kg/m²)")
            if mass_input_method == "Enter total mass (kg)":
                quantity = float(inputs.get("total_mass_kg", 0.0))
                if quantity <= 0:
                    raise ValueError("Enter the total installed mass in kg.")
                note = "total installed mass (kg)"
            else:
                grammage = float(inputs.get("grammage_kg_m2", 0.0))
                if grammage <= 0:
                    raise ValueError("Enter material grammage in kg/m².")
                quantity = area_m2 * grammage
                note = "wall area (m²) × grammage (kg/m²)"
            quantity_unit = "kg"

        elif method == "Mass by Volume + Density":
            thickness_in = float(inputs.get("thickness_in", 0.0))
            density = float(inputs.get("density_kg_m3", 0.0))
            if thickness_in <= 0 or density <= 0:
                raise ValueError("Enter thickness and density.")
            quantity = area_m2 * thickness_in * IN_TO_M * density
            quantity_unit = "kg"
            note = "area (m²) × thickness (m) × density (kg/m³)"

        elif method == "Mass by Item Grid":
            horizontal = float(inputs.get("horizontal_spacing_in", 0.0))
            vertical = float(inputs.get("vertical_spacing_in", 0.0))
            mass_each = float(inputs.get("mass_per_item_kg", 0.0))
            include_edges = inputs.get("include_wall_edges", "Yes")
            if horizontal <= 0 or vertical <= 0 or mass_each <= 0:
                raise ValueError("Enter horizontal spacing, vertical spacing, and mass per item.")
            columns = member_count(width_ft, horizontal, include_edges)
            rows = member_count(height_ft, vertical, include_edges)
            quantity = columns * rows * mass_each
            quantity_unit = "kg"
            note = "grid columns × grid rows × mass per item"

        elif method == "Mass by Linear Weight":
            orientation = inputs.get("orientation", "Vertical")
            spacing = float(inputs.get("spacing_in", 0.0))
            linear_weight = float(inputs.get("linear_weight_kg_m", 0.0))
            include_edges = inputs.get("include_edge_members", "Yes")
            if spacing <= 0 or linear_weight <= 0:
                raise ValueError("Enter spacing and linear weight.")
            span = width_ft if orientation == "Vertical" else height_ft
            length_each_ft = height_ft if orientation == "Vertical" else width_ft
            count = member_count(span, spacing, include_edges)
            quantity = count * length_each_ft * FT_TO_M * linear_weight
            quantity_unit = "kg"
            note = "member count × member length (m) × linear weight (kg/m)"

        elif method == "Linear Members":
            orientation = inputs.get("orientation", "Vertical")
            spacing = float(inputs.get("spacing_in", 0.0))
            include_edges = inputs.get("include_edge_members", "Yes")
            if spacing <= 0:
                raise ValueError("Enter member spacing.")
            span = width_ft if orientation == "Vertical" else height_ft
            length_each_ft = height_ft if orientation == "Vertical" else width_ft
            count = member_count(span, spacing, include_edges)
            quantity = count * length_each_ft * FT_TO_M
            quantity_unit = "m"
            note = "member count × member length (m)"

        elif method == "Unit Grid":
            use_horizontal = inputs.get("use_horizontal_spacing", "Yes") == "Yes"
            use_vertical = inputs.get("use_vertical_spacing", "Yes") == "Yes"
            include_edges = inputs.get("include_wall_edges", "Yes")

            columns = 1
            rows = 1
            directions = []

            if use_horizontal:
                horizontal = float(inputs.get("horizontal_spacing_in", 0.0))
                if horizontal <= 0:
                    raise ValueError("Enter horizontal spacing.")
                columns = member_count(width_ft, horizontal, include_edges)
                directions.append("horizontal count")

            if use_vertical:
                vertical = float(inputs.get("vertical_spacing_in", 0.0))
                if vertical <= 0:
                    raise ValueError("Enter vertical spacing.")
                rows = member_count(height_ft, vertical, include_edges)
                directions.append("vertical count")

            quantity = columns * rows
            quantity_unit = "units"
            if use_horizontal and use_vertical:
                note = "horizontal count × vertical count"
            elif directions:
                note = directions[0]
            else:
                note = "one unit for the wall"

        elif method == "Insulation R-value":
            required_r = float(inputs.get("required_r", 0.0))
            reference_type = inputs.get("epd_reference_type", "RSI (SI)")
            reference_value = float(inputs.get("epd_reference_value", 0.0))
            if required_r <= 0 or reference_value <= 0:
                raise ValueError("Enter required R-value and EPD reference R/RSI.")
            required_rsi = required_r * R_TO_RSI
            reference_rsi = reference_value * R_TO_RSI if reference_type == "R (US)" else reference_value
            quantity = area_m2 * required_rsi / reference_rsi
            quantity_unit = "m²-equivalent"
            note = "area (m²) × required RSI ÷ EPD reference RSI"

        elif method == "Wood Stud Framing":
            stud_size = inputs.get("stud_size", "2x4")
            spacing = float(inputs.get("spacing_in", 0.0))
            include_edges = inputs.get("include_edge_studs", "Yes")
            if stud_size not in WOOD_SIZES:
                raise ValueError("Choose a valid stud size.")
            if spacing <= 0:
                raise ValueError("Enter stud spacing.")
            count = member_count(width_ft, spacing, include_edges)
            actual_width_in, actual_depth_in = WOOD_SIZES[stud_size]
            cross_section_ft2 = actual_width_in * actual_depth_in / 144.0
            volume_ft3 = count * height_ft * cross_section_ft2
            quantity = volume_ft3 * FT3_TO_M3
            quantity_unit = "m³"
            note = "stud count × height × actual cross-section × ft³-to-m³"

        elif method == "Steel Stud Framing":
            depth_in = float(inputs.get("stud_depth_in", 0.0))
            gauge = str(inputs.get("gauge", "18"))
            spacing = float(inputs.get("spacing_in", 0.0))
            include_edges = inputs.get("include_edge_studs", "Yes")
            if depth_in <= 0 or spacing <= 0:
                raise ValueError("Enter stud depth and spacing.")
            if gauge not in STEEL_GAUGE_MM:
                raise ValueError("Choose a valid steel gauge.")
            count = member_count(width_ft, spacing, include_edges)
            total_length_m = count * height_ft * FT_TO_M
            strip_width_m = (depth_in + 2 * STEEL_FLANGE_IN + 2 * STEEL_LIP_IN) * IN_TO_M
            thickness_m = STEEL_GAUGE_MM[gauge] / 1000.0
            kg_per_m = strip_width_m * thickness_m * STEEL_DENSITY_KG_M3
            quantity = total_length_m * kg_per_m
            quantity_unit = "kg"
            note = "stud length × approximate C-section steel area × steel density"

        else:
            raise ValueError(f"Unsupported calculation method: {method}")

        emitted = quantity * float(epd["emitted"])
        stored = quantity * float(epd.get("stored", 0.0))
        net = emitted + stored
        emitted_intensity = emitted / area_m2 if area_m2 else 0.0
        net_intensity = net / area_m2 if area_m2 else 0.0

        base.update({
            "valid": True,
            "status": "Ready",
            "quantity": quantity,
            "quantity_unit": quantity_unit,
            "emitted": emitted,
            "stored": stored,
            "net": net,
            "emitted_intensity": emitted_intensity,
            "net_intensity": net_intensity,
            "name": epd["name"],
            "category": epd["category"],
            "method": method,
            "unit": epd["unit"],
            "formula_note": note,
            "epd_emitted": float(epd["emitted"]),
            "epd_stored": float(epd.get("stored", 0.0)),
            "source": epd.get("source", ""),
            "source_declared_unit": epd.get("source_declared_unit", ""),
        })
        return base

    except (TypeError, ValueError, ZeroDivisionError) as exc:
        base.update({
            "status": "Check inputs",
            "error": str(exc),
            "name": epd["name"],
            "category": epd["category"],
            "method": method,
            "unit": epd["unit"],
            "source": epd.get("source", ""),
        })
        return base


def calculate_assembly(assembly: dict[str, Any]) -> dict[str, Any]:
    rows = [calculate_material(assembly, material) for material in assembly.get("materials", [])]
    included = [row for row in rows if row["status"] != "Not selected"]
    ready = [row for row in rows if row["valid"]]
    width = float(assembly.get("width_ft", 0.0))
    height = float(assembly.get("height_ft", 0.0))
    area_ft2 = width * height
    area_m2 = area_ft2 * FT2_TO_M2
    emitted = sum(row["emitted"] for row in ready)
    stored = sum(row["stored"] for row in ready)
    net = emitted + stored
    return {
        "rows": rows,
        "area_ft2": area_ft2,
        "area_m2": area_m2,
        "emitted": emitted,
        "stored": stored,
        "net": net,
        "emitted_intensity": emitted / area_m2 if area_m2 else 0.0,
        "net_intensity": net / area_m2 if area_m2 else 0.0,
        "selected_count": len(included),
        "ready_count": len(ready),
        "status": "Not started" if not included else ("Ready" if len(included) == len(ready) else "Check inputs"),
    }

# =============================================================================
# INPUT RENDERING
# =============================================================================


def number_field(material: dict[str, Any], key: str, label: str, widget_key: str, default: float, step: float = 1.0, help_text: str | None = None) -> float:
    value = float(input_value(material, key, default))
    entered = st.number_input(label, min_value=0.0, value=value, step=step, key=widget_key, help=help_text)
    return set_input(material, key, float(entered))


def integer_field(material: dict[str, Any], key: str, label: str, widget_key: str, default: int = 0) -> int:
    value = int(input_value(material, key, default))
    entered = st.number_input(label, min_value=0, value=value, step=1, key=widget_key)
    return set_input(material, key, int(entered))


def dropdown_field(material: dict[str, Any], key: str, label: str, options: list[str], widget_key: str, default: str) -> str:
    current = input_value(material, key, default)
    entered = st.selectbox(label, options, index=select_index(options, current), key=widget_key)
    return set_input(material, key, entered)


def render_method_inputs(material: dict[str, Any], method: str, prefix: str) -> None:
    st.markdown('<div class="section-label">Required installation inputs</div>', unsafe_allow_html=True)

    if method == "Area":
        st.info("No additional input is required. The full wall area is used.")

    elif method == "Volume Layer":
        number_field(material, "thickness_in", "Product thickness (in)", f"{prefix}_thickness", 0.5, 0.125)

    elif method == "Mass by Grammage":
        mass_input_method = dropdown_field(
            material,
            "mass_input_method",
            "How do you know the installed mass?",
            ["Use grammage (kg/m²)", "Enter total mass (kg)"],
            f"{prefix}_mass_input_method",
            "Use grammage (kg/m²)",
        )
        if mass_input_method == "Enter total mass (kg)":
            number_field(
                material,
                "total_mass_kg",
                "Total installed mass (kg)",
                f"{prefix}_total_mass",
                1.0,
                0.1,
            )
            st.caption("Carbon = EPD GWP (kgCO₂e/kg) × total mass (kg).")
        else:
            number_field(
                material,
                "grammage_kg_m2",
                "Grammage (kg/m²)",
                f"{prefix}_grammage",
                1.0,
                0.1,
            )
            st.caption("Mass = wall area (m²) × grammage (kg/m²). Carbon = EPD GWP × mass.")

    elif method == "Mass by Volume + Density":
        c1, c2 = st.columns(2)
        with c1:
            number_field(material, "thickness_in", "Product thickness (in)", f"{prefix}_thickness", 0.5, 0.125)
        with c2:
            number_field(material, "density_kg_m3", "Density (kg/m³)", f"{prefix}_density", 500.0, 10.0)

    elif method == "Mass by Item Grid":
        c1, c2 = st.columns(2)
        with c1:
            number_field(material, "horizontal_spacing_in", "Horizontal spacing (in)", f"{prefix}_h_spacing", 16.0, 1.0)
        with c2:
            number_field(material, "vertical_spacing_in", "Vertical spacing (in)", f"{prefix}_v_spacing", 24.0, 1.0)
        c1, c2 = st.columns(2)
        with c1:
            number_field(material, "mass_per_item_kg", "Mass per item (kg)", f"{prefix}_mass_each", 0.25, 0.05)
        with c2:
            dropdown_field(material, "include_wall_edges", "Include wall edges?", ["Yes", "No"], f"{prefix}_wall_edges", "Yes")

    elif method == "Mass by Linear Weight":
        c1, c2 = st.columns(2)
        with c1:
            dropdown_field(material, "orientation", "Orientation", ["Vertical", "Horizontal"], f"{prefix}_orientation", "Vertical")
        with c2:
            number_field(material, "spacing_in", "Spacing (in)", f"{prefix}_spacing", 16.0, 1.0)
        c1, c2 = st.columns(2)
        with c1:
            number_field(material, "linear_weight_kg_m", "Linear weight (kg/m)", f"{prefix}_linear_weight", 1.0, 0.1)
        with c2:
            dropdown_field(material, "include_edge_members", "Include edge members?", ["Yes", "No"], f"{prefix}_edges", "Yes")

    elif method == "Linear Members":
        c1, c2 = st.columns(2)
        with c1:
            dropdown_field(material, "orientation", "Orientation", ["Vertical", "Horizontal"], f"{prefix}_orientation", "Vertical")
        with c2:
            number_field(material, "spacing_in", "Spacing (in)", f"{prefix}_spacing", 16.0, 1.0)
        dropdown_field(material, "include_edge_members", "Include edge members?", ["Yes", "No"], f"{prefix}_edges", "Yes")

    elif method == "Unit Grid":
        c1, c2 = st.columns(2)
        with c1:
            use_horizontal = dropdown_field(
                material,
                "use_horizontal_spacing",
                "Use horizontal spacing?",
                ["Yes", "No"],
                f"{prefix}_use_h_spacing",
                "Yes",
            )
        with c2:
            use_vertical = dropdown_field(
                material,
                "use_vertical_spacing",
                "Use vertical spacing?",
                ["Yes", "No"],
                f"{prefix}_use_v_spacing",
                "Yes",
            )

        spacing_columns = st.columns(2)
        if use_horizontal == "Yes":
            with spacing_columns[0]:
                number_field(material, "horizontal_spacing_in", "Horizontal spacing (in)", f"{prefix}_h_spacing", 16.0, 1.0)
        if use_vertical == "Yes":
            with spacing_columns[1]:
                number_field(material, "vertical_spacing_in", "Vertical spacing (in)", f"{prefix}_v_spacing", 24.0, 1.0)

        if use_horizontal == "Yes" or use_vertical == "Yes":
            dropdown_field(material, "include_wall_edges", "Include wall edges?", ["Yes", "No"], f"{prefix}_wall_edges", "Yes")
        else:
            st.info("One unit will be counted for the wall because neither spacing direction is used.")

    elif method == "Insulation R-value":
        c1, c2, c3 = st.columns(3)
        with c1:
            number_field(material, "required_r", "Required R-value", f"{prefix}_required_r", 20.0, 1.0)
        with c2:
            dropdown_field(material, "epd_reference_type", "EPD reference type", ["R (US)", "RSI (SI)"], f"{prefix}_reference_type", "RSI (SI)")
        with c3:
            number_field(material, "epd_reference_value", "EPD reference R / RSI", f"{prefix}_reference_value", 1.0, 0.1)

    elif method == "Wood Stud Framing":
        c1, c2, c3 = st.columns(3)
        with c1:
            dropdown_field(material, "stud_size", "Stud size", list(WOOD_SIZES), f"{prefix}_stud_size", "2x4")
        with c2:
            number_field(material, "spacing_in", "Stud spacing (in)", f"{prefix}_spacing", 16.0, 1.0)
        with c3:
            dropdown_field(material, "include_edge_studs", "Include edge studs?", ["Yes", "No"], f"{prefix}_edge_studs", "Yes")

    elif method == "Steel Stud Framing":
        c1, c2, c3, c4 = st.columns(4)
        with c1:
            number_field(material, "stud_depth_in", "Stud depth (in)", f"{prefix}_depth", 6.0, 0.5)
        with c2:
            dropdown_field(material, "gauge", "Gauge", list(STEEL_GAUGE_MM), f"{prefix}_gauge", "18")
        with c3:
            number_field(material, "spacing_in", "Stud spacing (in)", f"{prefix}_spacing", 16.0, 1.0)
        with c4:
            dropdown_field(material, "include_edge_studs", "Include edge studs?", ["Yes", "No"], f"{prefix}_edge_studs", "Yes")
        st.caption("Steel mass uses an editable industry-average C-section approximation: 7,850 kg/m³ density, 1.625 in flanges, and 0.5 in lips.")

